'use strict';
const fs = require('node:fs');
const path = process.argv[2];
if (!path) { console.error('Usage: node decide.cjs input.json'); process.exit(2); }
function fail(message) { throw new Error(message); }
function objectAt(obj, key) {
  if (!obj || typeof obj[key] !== 'object' || obj[key] === null || Array.isArray(obj[key])) fail(key + ' must be an object');
  return obj[key];
}
function stringAt(obj, key) {
  if (!obj || typeof obj[key] !== 'string' || obj[key].trim() === '') fail(key + ' must be a nonempty string');
  return obj[key];
}
function finiteAt(obj, key, max) {
  const value = obj && obj[key];
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0 || value > max) fail(key + ' must be finite, nonnegative, and <= ' + max);
  return value;
}
function positiveAt(obj, key, max) {
  const value = obj && obj[key];
  if (!Number.isInteger(value) || value <= 0 || value > max) fail(key + ' must be a positive bounded integer <= ' + max);
  return value;
}
function positiveNumberAt(obj, key, max) {
  const value = obj && obj[key];
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0 || value > max) fail(key + ' must be a finite positive number <= ' + max);
  return value;
}
try {
  const input = JSON.parse(fs.readFileSync(path, 'utf8'));
  const build = objectAt(input, 'build');
  const economics = objectAt(input, 'economics');
  const limits = objectAt(input, 'limits');
  const measurements = objectAt(input, 'measurements');
  const evidence = objectAt(input, 'evidence');
  ['model','revision','template','region','deploymentType'].forEach(k => stringAt(build, k));
  const acceleratorsPerInstance = positiveAt(economics, 'acceleratorsPerInstance', 128);
  const instances = positiveAt(economics, 'instances', 10000);
  const hours = positiveNumberAt(economics, 'hours', 8760);
  const rate = finiteAt(economics, 'rate', 1000000);
  const maxCost = finiteAt(limits, 'maxCost', 1000000000);
  const maxP95Ms = positiveNumberAt(limits, 'maxP95Ms', 86400000);
  const maxRejectionRate = finiteAt(limits, 'maxRejectionRate', 1);
  const minEvalScore = finiteAt(limits, 'minEvalScore', 1);
  const maxInstances = positiveAt(limits, 'maxInstances', 10000);
  const maxAccelerators = positiveAt(limits, 'maxAccelerators', 1000000);
  const p95Ms = finiteAt(measurements, 'p95Ms', 86400000);
  const rejectionRate = finiteAt(measurements, 'rejectionRate', 1);
  const evalScore = finiteAt(measurements, 'evalScore', 1);
  const calculatedCost = acceleratorsPerInstance * instances * hours * rate;
  if (!Number.isFinite(calculatedCost)) fail('calculated cost must be finite');
  const requiredEvidence = ['authorization','modelLicense','deploymentManifest','endpointNetwork','negativeTests','evaluation','loadQuota','costAssumptions','telemetryAlerts','rollbackRehearsal','alternativeAdapter'];
  const missingEvidence = requiredEvidence.filter(k => evidence[k] !== true);
  const reasons = [];
  if (missingEvidence.length) reasons.push('MISSING_EVIDENCE:' + missingEvidence.join(','));
  if (instances > maxInstances || acceleratorsPerInstance * instances > maxAccelerators) reasons.push('CAPACITY_LIMIT');
  if (calculatedCost > maxCost) reasons.push('BUDGET_LIMIT');
  if (p95Ms > maxP95Ms) reasons.push('P95_LATENCY_LIMIT');
  if (rejectionRate > maxRejectionRate) reasons.push('REJECTION_LIMIT');
  if (evalScore < minEvalScore) reasons.push('EVALUATION_LIMIT');
  if (evidence.recoveryPassed !== true) reasons.push('RECOVERY_NOT_PASSED');
  const decision = reasons.length === 0 ? 'ELIGIBLE_FOR_QUALIFICATION_REVIEW' : 'BLOCKED';
  console.log(JSON.stringify({decision,calculatedCost,missingEvidence,reasons,build:{model:build.model,revision:build.revision,template:build.template}}));
} catch (error) {
  console.log(JSON.stringify({decision:'BLOCKED',error:'INVALID_INPUT:' + error.message}));
  process.exitCode = 1;
}
